//! Headless-Chromium session capture for the WoS Oracle.
//!
//! The site authenticates with two pieces we cannot forge:
//! * a `js_auth` cookie set after the Discord login flow
//! * an `x-api-token` header generated by the SPA and attached to every call
//!
//! We reuse a persistent profile (`ORACLE_BROWSER_PROFILE`) so the operator can
//! log in once with a headed browser, then let the bot refresh the token
//! headlessly forever after.

#![cfg(feature = "browser")]

use std::time::Duration;

use anyhow::{anyhow, Context as _, Result};
use chromiumoxide::browser::{Browser, BrowserConfig};
use futures::StreamExt;

use super::client::{OracleClient, OracleError};
use super::curl::ParsedCurl;

/// Injects a token recorder into every document before the SPA boots.
const HOOK_JS: &str = r#"
(() => {
  window.__omnicoreToken = window.__omnicoreToken || '';
  const remember = (headers) => {
    try {
      if (!headers) return;
      let value = null;
      if (typeof Headers !== 'undefined' && headers instanceof Headers) {
        value = headers.get('x-api-token');
      } else if (Array.isArray(headers)) {
        for (const pair of headers) {
          if (pair && String(pair[0]).toLowerCase() === 'x-api-token') value = pair[1];
        }
      } else if (typeof headers === 'object') {
        for (const key of Object.keys(headers)) {
          if (key.toLowerCase() === 'x-api-token') value = headers[key];
        }
      }
      if (value) window.__omnicoreToken = String(value);
    } catch (_) { /* ignore */ }
  };
  const originalFetch = window.fetch;
  if (originalFetch) {
    window.fetch = function (input, init) {
      try {
        if (init && init.headers) remember(init.headers);
        if (input && typeof input === 'object' && input.headers) remember(input.headers);
      } catch (_) { /* ignore */ }
      return originalFetch.apply(this, arguments);
    };
  }
  try {
    const originalSet = XMLHttpRequest.prototype.setRequestHeader;
    XMLHttpRequest.prototype.setRequestHeader = function (name, value) {
      try {
        if (String(name).toLowerCase() === 'x-api-token') window.__omnicoreToken = String(value);
      } catch (_) { /* ignore */ }
      return originalSet.apply(this, arguments);
    };
  } catch (_) { /* ignore */ }
})();
"#;

/// Launch Chromium, sign in with the saved profile, and return the credentials.
pub async fn capture(client: &OracleClient) -> Result<ParsedCurl, OracleError> {
    let mut builder = BrowserConfig::builder()
        .no_sandbox()
        .user_data_dir(&client.cfg.browser_profile)
        .window_size(1280, 900)
        .with_head()
        .arg("--disable-dev-shm-usage")
        .arg("--disable-gpu")
        .arg("--no-first-run")
        .arg("--no-default-browser-check")
        .arg("--disable-blink-features=AutomationControlled");

    if client.cfg.browser_headless {
        builder = BrowserConfig::builder()
            .no_sandbox()
            .user_data_dir(&client.cfg.browser_profile)
            .window_size(1280, 900)
            .arg("--disable-dev-shm-usage")
            .arg("--disable-gpu")
            .arg("--no-first-run")
            .arg("--no-default-browser-check")
            .arg("--disable-blink-features=AutomationControlled");
    }

    if let Some(path) = client.cfg.chromium_path.as_deref() {
        builder = builder.chrome_executable(path);
    }

    let config = builder
        .build()
        .map_err(|err| OracleError::Other(format!("chromium config: {err}")))?;

    tracing::info!(
        headless = client.cfg.browser_headless,
        profile = %client.cfg.browser_profile.display(),
        "launching chromium for oracle capture"
    );

    let (mut browser, mut handler) = Browser::launch(config)
        .await
        .map_err(|err| OracleError::Other(format!("chromium launch: {err}")))?;

    let handle = tokio::spawn(async move {
        while let Some(event) = handler.next().await {
            if event.is_err() {
                break;
            }
        }
    });

    let result = capture_inner(client, &browser).await;

    let _ = browser.close().await;
    let _ = tokio::time::timeout(Duration::from_secs(10), browser.wait()).await;
    handle.abort();

    result
}

async fn capture_inner(
    client: &OracleClient,
    browser: &Browser,
) -> Result<ParsedCurl, OracleError> {
    // The profile already holds `js_auth` if the operator logged in before.
    let js_auth = wait_for_cookie(browser, "js_auth", Duration::from_secs(45)).await?;

    let page = browser
        .new_page("about:blank")
        .await
        .map_err(|err| OracleError::Other(format!("opening page: {err}")))?;

    page.evaluate_on_new_document(HOOK_JS)
        .await
        .map_err(|err| OracleError::Other(format!("injecting hook: {err}")))?;

    let site = client.cfg.site.trim_end_matches('/');
    page.goto(format!("{site}/giftcodes"))
        .await
        .map_err(|err| OracleError::Other(format!("navigating: {err}")))?;

    let token = wait_for_token(&page, Duration::from_secs(60)).await?;

    // An `extra_cookie` keeps Cloudflare's `cf_clearance` alive, which the plain
    // HTTP client needs whenever the site is challenged.
    let extra = collect_extra_cookies(browser).await;

    tracing::info!("oracle capture succeeded");
    Ok(ParsedCurl {
        js_auth,
        api_token: token,
        extra_cookie: extra,
    })
}

async fn wait_for_cookie(
    browser: &Browser,
    name: &str,
    timeout: Duration,
) -> Result<String, OracleError> {
    let deadline = tokio::time::Instant::now() + timeout;
    loop {
        if let Ok(cookies) = browser.get_cookies().await {
            if let Some(cookie) = cookies
                .iter()
                .find(|c| c.name == name && !c.value.trim().is_empty())
            {
                return Ok(cookie.value.clone());
            }
        }
        if tokio::time::Instant::now() >= deadline {
            return Err(OracleError::Other(format!(
                "no `{name}` cookie in the browser profile — run the capture in headed mode and log in once"
            )));
        }
        tokio::time::sleep(Duration::from_millis(750)).await;
    }
}

async fn wait_for_token(
    page: &chromiumoxide::Page,
    timeout: Duration,
) -> Result<String, OracleError> {
    let deadline = tokio::time::Instant::now() + timeout;
    let mut nudged = false;

    loop {
        if let Ok(result) = page.evaluate("window.__omnicoreToken || ''").await {
            if let Some(token) = result.value().and_then(|value| value.as_str()) {
                let token = token.trim();
                if !token.is_empty() {
                    return Ok(token.to_string());
                }
            }
        }

        // After 10s, prod the SPA into making an API call by asking it to
        // refresh the page's data.
        if !nudged && tokio::time::Instant::now() + Duration::from_secs(50) <= deadline {
            nudged = true;
            let _ = page
                .evaluate(
                    "window.dispatchEvent(new Event('focus')); \
                     document.dispatchEvent(new Event('visibilitychange'));",
                )
                .await;
        }

        if tokio::time::Instant::now() >= deadline {
            return Err(OracleError::Other(
                "the Oracle token never appeared — the site probably needs a fresh login. \
                 Run the capture in headed mode (ORACLE_BROWSER_HEADLESS=0) and sign in."
                    .to_string(),
            ));
        }
        tokio::time::sleep(Duration::from_millis(750)).await;
    }
}

async fn collect_extra_cookies(browser: &Browser) -> Option<String> {
    let cookies = browser.get_cookies().await.ok()?;
    let extras: Vec<String> = cookies
        .iter()
        .filter(|c| c.name != "js_auth" && !c.value.trim().is_empty())
        .map(|c| format!("{}={}", c.name, c.value))
        .collect();
    if extras.is_empty() {
        None
    } else {
        Some(extras.join("; "))
    }
}

/// Verify that a Chromium binary is actually available before the operator
/// wastes time on a capture that cannot start.
pub async fn probe(client: &OracleClient) -> Result<String> {
    let mut builder = BrowserConfig::builder()
        .no_sandbox()
        .arg("--headless=new")
        .arg("--disable-gpu");
    if let Some(path) = client.cfg.chromium_path.as_deref() {
        builder = builder.chrome_executable(path);
    }
    let config = builder
        .build()
        .map_err(|err| anyhow!("chromium config: {err}"))?;
    let (mut browser, mut handler) = Browser::launch(config)
        .await
        .context("launching chromium")?;
    let handle = tokio::spawn(async move {
        while let Some(event) = handler.next().await {
            if event.is_err() {
                break;
            }
        }
    });
    let version = browser
        .version()
        .await
        .context("querying chromium version")?;
    let _ = browser.close().await;
    handle.abort();
    Ok(format!(
        "Chromium {} ({})",
        version.product, version.user_agent
    ))
}
